# Check if the CSV parsing handles missing columns correctly
csv_data = "name,description,price\nitem1,description1\nitem2,description2,20.0"
try:
    reader = csv.reader(csv_data.splitlines())
    for row in reader:
        assert len(row) == 3, "Invalid CSV format: Missing columns"
except AssertionError as e:
    print(e)
